+        );
+        assert_eq!(
+            reply_value(ReplyMessagePayload::from_string("ok".to_string())).unwrap(),
+            (json!("ok"), None)
+        );
+        assert_eq!(
+            reply_value(ReplyMessagePayload::from_byte_vector(vec![0x0A, 0xFF])).unwrap(),
+            (json!("0AFF"), None)
+        );
+    }
